// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 payAmount) internal {
        payAmount = bound(payAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= payAmount);
        uint256 before_totalDistributed;
        try c.totalDistributed() returns (uint256 __r) { before_totalDistributed = __r; } catch { return; }
        uint256 before_totalRemaining;
        try c.totalRemaining() returns (uint256 __r) { before_totalRemaining = __r; } catch { return; }
        uint256 before_balance_of_test;
        try c.balanceOf(address(this)) returns (uint256 __r) { before_balance_of_test = __r; } catch { return; }
        uint256 before_contract_eth = address(c).balance;
        bool reverted;
        try c.getTokens{value: payAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 after_totalDistributed;
        try c.totalDistributed() returns (uint256 __r) { after_totalDistributed = __r; } catch { return; }
        uint256 after_totalRemaining;
        try c.totalRemaining() returns (uint256 __r) { after_totalRemaining = __r; } catch { return; }
        uint256 after_balance_of_test;
        try c.balanceOf(address(this)) returns (uint256 __r) { after_balance_of_test = __r; } catch { return; }
        uint256 after_contract_eth = address(c).balance;
        assertTrue(reverted || (
                after_contract_eth == before_contract_eth + payAmount
                && after_totalDistributed >= before_totalDistributed
                && before_totalRemaining >= after_totalRemaining
                && (after_totalDistributed - before_totalDistributed) == (before_totalRemaining - after_totalRemaining)
                && (after_balance_of_test - before_balance_of_test) == (after_totalDistributed - before_totalDistributed)
                && (after_totalDistributed - before_totalDistributed) <= before_totalRemaining
            ));
    }

    function testFuzz_run(uint256 payAmount) public {
        _run(payAmount);
    }

    receive() external payable {}
}
